def get_or_create_vinculo(apps, dic, funcionario):
    Vinculo = apps.get_model('comum.Vinculo')
    ContentType = apps.get_model('contenttypes.ContentType')
    tipo_relacionamento_prestador = ContentType.objects.get(app_label='comum', model='prestadorservico')
    tipo_relacionamento_servidor = ContentType.objects.get(app_label='rh', model='servidor')

    if funcionario.id in dic:
        vinculo_id = dic[funcionario.id]
    else:
        if hasattr(funcionario, 'servidor'):
            relacionamento = funcionario.servidor
            tipo_relacionamento = tipo_relacionamento_servidor
        else:
            relacionamento = funcionario.prestadorservico
            tipo_relacionamento = tipo_relacionamento_prestador
        vinculo_id = Vinculo.objects.create(pessoa=funcionario.pessoa_ptr, tipo_relacionamento=tipo_relacionamento, id_relacionamento=relacionamento.id, secret=funcionario.pessoa_ptr.id).id
        print(f'\n\nVínculo {vinculo_id} criado de funcionario {funcionario}\n\n')

    return vinculo_id


def atualizar_dados(apps, schema):
    Funcionario = apps.get_model('rh.funcionario')
    HorarioAgendado = apps.get_model('rh.horarioagendado')
    Vinculo = apps.get_model('comum.vinculo')

    vinculos = Vinculo.objects.all()
    dic = {}
